sctp_process_asconf_delete_ip(struct sockaddr *src,
                              struct sctp_asconf_paramhdr *aph,
                              struct sctp_tcb *stcb, int response_required)
{
        struct mbuf *m_reply = NULL;
        union sctp_sockstore store;
        struct sctp_paramhdr *ph;
        uint16_t param_type, aparam_length;
#if defined(INET) || defined(INET6)
        uint16_t param_length;
#endif
        struct sockaddr *sa;
        int zero_address = 0;
        int result;
#ifdef INET
        struct sockaddr_in *sin;
        struct sctp_ipv4addr_param *v4addr;
#endif
#ifdef INET6
        struct sockaddr_in6 *sin6;
        struct sctp_ipv6addr_param *v6addr;
#endif

        aparam_length = ntohs(aph->ph.param_length);
        ph = (struct sctp_paramhdr *)(aph + 1);
        param_type = ntohs(ph->param_type);
#if defined(INET) || defined(INET6)
        param_length = ntohs(ph->param_length);
#endif
        sa = &store.sa;
        switch (param_type) {
#ifdef INET
        case SCTP_IPV4_ADDRESS:
                if (param_length != sizeof(struct sctp_ipv4addr_param)) {
                        /* invalid param size */
                        return (NULL);
                }
                v4addr = (struct sctp_ipv4addr_param *)ph;
                sin = &store.sin;
                memset(sin, 0, sizeof(*sin));
                sin->sin_family = AF_INET;
#ifdef HAVE_SIN_LEN
                sin->sin_len = sizeof(struct sockaddr_in);
#endif
                sin->sin_port = stcb->rport;
                sin->sin_addr.s_addr = v4addr->addr;
                if (sin->sin_addr.s_addr == INADDR_ANY)
                        zero_address = 1;
                SCTPDBG(SCTP_DEBUG_ASCONF1,
                        "process_asconf_delete_ip: deleting ");
                SCTPDBG_ADDR(SCTP_DEBUG_ASCONF1, sa);
                break;
#endif
#ifdef INET6
        case SCTP_IPV6_ADDRESS:
                if (param_length != sizeof(struct sctp_ipv6addr_param)) {
                        /* invalid param size */
                        return (NULL);
                }
                v6addr = (struct sctp_ipv6addr_param *)ph;
                sin6 = &store.sin6;
                memset(sin6, 0, sizeof(*sin6));
                sin6->sin6_family = AF_INET6;
#ifdef HAVE_SIN6_LEN
                sin6->sin6_len = sizeof(struct sockaddr_in6);
#endif
                sin6->sin6_port = stcb->rport;
                memcpy(&sin6->sin6_addr, v6addr->addr,
                    sizeof(struct in6_addr));
                if (IN6_IS_ADDR_UNSPECIFIED(&sin6->sin6_addr))
                        zero_address = 1;
                SCTPDBG(SCTP_DEBUG_ASCONF1,
                        "process_asconf_delete_ip: deleting ");
                SCTPDBG_ADDR(SCTP_DEBUG_ASCONF1, sa);
                break;
#endif
        default:
                m_reply = sctp_asconf_error_response(aph->correlation_id,
                    SCTP_CAUSE_UNRESOLVABLE_ADDR, (uint8_t *) aph,
                    aparam_length);
                return (m_reply);
        }

        /* make sure the source address is not being deleted */
        if (sctp_cmpaddr(sa, src)) {
                /* trying to delete the source address! */
                SCTPDBG(SCTP_DEBUG_ASCONF1, "process_asconf_delete_ip: tried to delete source addr\n");
